/** Tool name, as written on the site, to its logo. Tools without a logo are left out. */
const toolLogos: Record<string, string> = {
  "React": "react",
  "Next.js": "nextdotjs",
  "TypeScript": "typescript",
  "JavaScript": "javascript",
  "Tailwind CSS": "tailwindcss",
  "Livewire": "livewire",
  "Laravel": "laravel",
  "PHP": "php",
  "Node.js": "nodedotjs",
  "Python": "python",
  "Django": "django",
  "PostgreSQL": "postgresql",
  "MySQL": "mysql",
  "Redis": "redis",
  "Redis queues": "redis",
  "JWT": "jsonwebtokens",
  "Docker": "docker",
  "GitHub Actions": "githubactions",
  "Linux": "linux",
  "nginx": "nginx",
  "Cloudflare": "cloudflare",
  "Vercel": "vercel",
  "Fedora RPM": "fedora",
  "Bash": "gnubash",
  "Podman": "podman",
  "QML": "qt",
  "Qt 6": "qt",
  "Hyprland": "hyprland",
  "Wayland": "wayland",
  "k6": "k6",
  "QEMU/KVM": "qemu",
  "GDM": "gnome",
}

export function techIcon(tool: string): TechIcon | undefined {
  const slug = toolLogos[tool]
  return slug ? icons[slug] : undefined
}
